<?php
if (!defined('ABSPATH')) exit;
function gim_vji_start($job_id,$customer_id){ global $wpdb; $code=(string)random_int(100000,999999); $digest=hash_hmac('sha256',$job_id.'|'.$customer_id.'|'.$code,wp_salt('auth')); set_transient('gim_vji_'.$job_id,['customer'=>$customer_id,'digest'=>$digest,'tries'=>0],10*MINUTE_IN_SECONDS); $u=get_userdata($customer_id); if($u)wp_mail($u->user_email,'Verify your GOTITMATE job','Your job verification code is '.$code.'.'); $wpdb->update(gim_table('jobs'),['vji_status'=>'code_sent','updated_at'=>gim_now()],['id'=>$job_id]); return true; }
function gim_vji_verify($job_id,$customer_id,$code){ global $wpdb; $d=get_transient('gim_vji_'.$job_id); if(!$d||(int)$d['customer']!==$customer_id)return false; $d['tries']++; if($d['tries']>6){delete_transient('gim_vji_'.$job_id);return false;} set_transient('gim_vji_'.$job_id,$d,10*MINUTE_IN_SECONDS); $digest=hash_hmac('sha256',$job_id.'|'.$customer_id.'|'.$code,wp_salt('auth')); if(!hash_equals($d['digest'],$digest))return false; delete_transient('gim_vji_'.$job_id); $wpdb->update(gim_table('jobs'),['vji_status'=>'verified','vji_digest'=>hash('sha256',$job_id.'|'.$customer_id.'|verified'),'status'=>'verified_intent','updated_at'=>gim_now()],['id'=>$job_id]); gim_audit('vji.verified','job',(string)$job_id); return true; }
